    html: `<!DOCTYPE html>\n<html>\n<head>\n<meta charset="UTF-8">\n<title>Space Shooter</title>\n<style>\nbody{margin:0;background:#05050c;color:#fff;font-family:monospace;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh}\ncanvas{border:2px solid #38bdf8;box-shadow:0 0 20px rgba(56,189,248,.3);background:#020617}\n</style>\n</head>\n<body>\n<h2>STARLIGHT DEFENDER</h2>\n<canvas id="c" width="480" height="540"></canvas>\n<p>Arrows / WASD to move &middot; Space to fire</p>\n<script>\nconst c=document.getElementById("c"),ctx=c.getContext("2d");\nlet p={x:220,y:480},shots=[],score=0;\nwindow.onkeydown=e=>{\n  if(e.code==="Space")shots.push({x:p.x+18,y:p.y});\n  if(e.code==="ArrowLeft"||e.code==="KeyA")p.x=Math.max(10,p.x-20);\n  if(e.code==="ArrowRight"||e.code==="KeyD")p.x=Math.min(430,p.x+20);\n};\nfunction loop(){\n  ctx.fillStyle="#020617";ctx.fillRect(0,0,480,540);\n  ctx.fillStyle="#38bdf8";ctx.fillRect(p.x,p.y,40,16);\n  ctx.fillStyle="#f43f5e";shots.forEach(s=>{s.y-=8;ctx.fillRect(s.x,s.y,4,12)});\n  shots=shots.filter(s=>s.y>0);\n  ctx.fillStyle="#fff";ctx.fillText("SCORE: "+score,16,24);\n  requestAnimationFrame(loop);\n}\nloop();\n<\/script>\n</body>\n</html>`
